{"path": "create_tables.sql", "content": "-- Create and load interactions
CREATE TABLE IF NOT EXISTS workspace.${MLPAB_DATABRICKS_SCHEMA#workspace.}.interactions (
  user_id STRING,
  item_id STRING
);

COPY INTO workspace.${MLPAB_DATABRICKS_SCHEMA#workspace.}.interactions
FROM "dbfs:/Volumes/workspace/${MLPAB_DATABRICKS_SCHEMA#workspace.}/input_volume/interactions.csv"
