FORMAT_OPTIONS ('header' = 'true', 'inferSchema' = 'true')
COPY_OPTIONS ('mergeSchema' = 'true');

-- Create and load user_embeddings
CREATE TABLE IF NOT EXISTS workspace.${MLPAB_DATABRICKS_SCHEMA#workspace.}.user_embeddings (
  user_id STRING,
  e1 DOUBLE, e2 DOUBLE, e3 DOUBLE, e4 DOUBLE, e5 DOUBLE, e6 DOUBLE, e7 DOUBLE, e8 DOUBLE
);

COPY INTO workspace.${MLPAB_DATABRICKS_SCHEMA#workspace.}.user_embeddings
FROM "dbfs:/Volumes/workspace/${MLPAB_DATABRICKS_SCHEMA#workspace.}/input_volume/user_embeddings.csv"
FILEFORMAT = CSV
FORMAT_OPTIONS ('header' = 'true', 'inferSchema' = 'true')
COPY_OPTIONS ('mergeSchema' = 'true');

-- Create and load item_embeddings
CREATE TABLE IF NOT EXISTS workspace.${MLPAB_DATABRICKS_SCHEMA#workspace.}.item_embeddings (
  item_id STRING,
  e1 DOUBLE, e2 DOUBLE, e3 DOUBLE, e4 DOUBLE, e5 DOUBLE, e6 DOUBLE, e7 DOUBLE, e8 DOUBLE
);

COPY INTO workspace.${MLPAB_DATABRICKS_SCHEMA#workspace.}.item_embeddings
FROM "dbfs:/Volumes/workspace/${MLPAB_DATABRICKS_SCHEMA#workspace.}/input_volume/item_embeddings.csv"
FILEFORMAT = CSV
FORMAT_OPTIONS ('header' = 'true', 'inferSchema' = 'true')
COPY_OPTIONS ('mergeSchema' = 'true');"}

